package com.example.dailylife.data.local

import androidx.room.*

@Entity(tableName="ledgers",indices=[Index(value=["ownerId","normalizedName"],unique=true)])
data class Ledger(@PrimaryKey val id:String=newId(),val ownerId:String,val name:String,val normalizedName:String,val currency:String="CNY",val isDefault:Boolean=false,val sortOrder:Int=0,val archivedAt:Long?=null)
@Entity(tableName="ledger_categories",indices=[Index(value=["ownerId","uniqueKey"],unique=true)])
data class LedgerCategory(@PrimaryKey val id:String=newId(),val ownerId:String,val name:String,val direction:String,val parentId:String?=null,val uniqueKey:String,val icon:String="category",val active:Boolean=true,val protected:Boolean=false,val sortOrder:Int=0)
@Entity(tableName="money_accounts",indices=[Index(value=["ownerId","normalizedName"],unique=true)])
data class MoneyAccount(@PrimaryKey val id:String=newId(),val ownerId:String,val name:String,val normalizedName:String,val accountType:String="cash",val openingBalanceMinor:Long=0,val openingAsOfDate:String,val note:String="",val tail:String="",val sortOrder:Int=0,val hidden:Boolean=false,val archivedAt:Long?=null)
@Entity(tableName="ledger_transactions",indices=[Index("ownerId"),Index("ledgerId"),Index("occurredOn"),Index("accountId"),Index("toAccountId"),Index("categoryId"),Index("originalExpenseId"),Index("claimId"),Index("relatedTransactionId"),Index(value=["externalKey"],unique=true),Index("deletedAt")])
data class LedgerTransaction(@PrimaryKey val id:String=newId(),val ownerId:String,val ledgerId:String,val type:String,val amountMinor:Long,val occurredOn:String,val occurredTime:String?=null,val zoneId:String="Asia/Shanghai",val occurredAt:Long?=null,val categoryId:String?=null,val accountId:String?=null,val toAccountId:String?=null,val paymentChannel:String="",val counterparty:String="",val location:String="",val subject:String="",val note:String="",val includeInBudget:Boolean=true,val originalExpenseId:String?=null,val claimId:String?=null,val relatedTransactionId:String?=null,val externalKey:String?=null,val importBatchId:String?=null,val createdAt:Long=System.currentTimeMillis(),val updatedAt:Long=createdAt,val revision:Long=1,val deletedAt:Long?=null,val saveKey:String="")
@Entity(tableName="account_entries",primaryKeys=["transactionId","accountId","role"],indices=[Index("accountId")])
data class AccountEntry(val transactionId:String,val accountId:String,val deltaMinor:Long,val role:String)
@Entity(tableName="ledger_drafts")
data class LedgerDraft(@PrimaryKey val id:String,val ownerId:String,val payload:String,val savedAt:Long=System.currentTimeMillis())
@Entity(tableName="transaction_templates")
data class TransactionTemplate(@PrimaryKey val id:String=newId(),val ownerId:String,val name:String,val payload:String)
@Entity(tableName="monthly_budgets",indices=[Index(value=["ledgerId","month","scopeKey"],unique=true)])
data class MonthlyBudget(@PrimaryKey val id:String=newId(),val ownerId:String,val ledgerId:String,val month:String,val categoryId:String?=null,val scopeKey:String="total",val limitMinor:Long,val alertsEnabled:Boolean=true)
@Entity(tableName="budget_alerts",primaryKeys=["budgetId","threshold"])
data class BudgetAlert(val budgetId:String,val threshold:Int,val triggeredAt:Long=System.currentTimeMillis(),val readAt:Long?=null)
@Entity(tableName="reimbursement_claims")
data class ReimbursementClaim(@PrimaryKey val id:String=newId(),val ownerId:String,val name:String,val settlementLedgerId:String,val submittedOn:String?=null,val status:String="draft",val needsReview:Boolean=false,val counterparty:String="",val note:String="",val revision:Long=1,val deletedAt:Long?=null)
@Entity(tableName="reimbursement_items",primaryKeys=["claimId","expenseId"],indices=[Index("expenseId")])
data class ReimbursementItem(val claimId:String,val expenseId:String,val requestedMinor:Long)
@Entity(tableName="ledger_change_logs",indices=[Index("entityId")])
data class LedgerChangeLog(@PrimaryKey val id:String=newId(),val entityId:String,val action:String,val summary:String,val createdAt:Long=System.currentTimeMillis())
@Entity(tableName="ledger_import_batches",indices=[Index(value=["source","sourceAccount","fileHash","ledgerId"],unique=true)])
data class LedgerImportBatch(@PrimaryKey val id:String=newId(),val ownerId:String,val source:String,val sourceAccount:String,val fileHash:String,val ledgerId:String,val accountId:String?=null,val mapping:String,val status:String="preview",val createdAt:Long=System.currentTimeMillis())
@Entity(tableName="ledger_import_rows",primaryKeys=["batchId","rowNumber"],indices=[Index("transactionId")])
data class LedgerImportRow(val batchId:String,val rowNumber:Int,val rawValues:String,val parsedValues:String,val dedupKey:String?=null,val transactionId:String?=null,val result:String="pending",val error:String="",val suspectedDuplicate:Boolean=false)
